async def asgi_app(scope, receive, send):
    # Asynchronous: can await I/O
    assert scope['type'] == 'http'

    await send({
        'type': 'http.response.start',
        'status': 200,
        'headers': [
            [b'content-type', b'text/plain'],
        ],
    })

    await send({
        'type': 'http.response.body',
        'body': b'Hello World',
    })

# Run with: uvicorn app:asgi_app
